
.char-page {
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  padding: 10px;
}

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  flex-wrap: wrap;
}

.presence-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex: none;
}

.name {
  font-weight: bold;
  font-size: 1.02rem;
}

.stage {
  color: var(--c-text-muted);
  font-size: 0.8rem;
}

.dep-label {
  margin-left: auto;
  color: var(--c-text-muted);
  font-size: 0.75rem;
}

.dep-track {
  width: 84px;
  height: 6px;
  border-radius: 3px;
  background: var(--c-panel-inner);
  overflow: hidden;
  flex: none;
}

.dep-fill {
  display: block;
  height: 100%;
  border-radius: 3px;
  transition: width 0.25s ease;
}

.dep-value {
  font-size: 0.8rem;
  color: var(--c-text-muted);
  min-width: 2ch;
  text-align: right;
}

.cycle {
  padding: 2px 9px;
  border-radius: 9px;
  font-size: 0.75rem;
  background: var(--c-panel);
  border: 1px solid var(--c-border-soft);
  color: var(--c-text-muted);
  flex: none;

  &.danger {
    background: var(--c-danger-bg);
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.voice-label {
  color: var(--c-text-faint);
  font-size: 0.72rem;
}

.voice-text {
  padding: 8px 10px;
  background: var(--c-panel-inner);
  border-left: 3px solid;
  border-radius: 6px;
  color: var(--c-text);
  font-size: 0.88rem;
  white-space: pre-wrap;
  word-break: break-word;
}

@media (max-width: 480px) {
  .dep-track {
    width: 64px;
  }

  .name {
    font-size: 0.95rem;
  }
}
