
.overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  background: rgba(10, 11, 16, 0.82);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 12px;
}

.panel {
  width: 100%;
  max-width: 560px;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  gap: 8px;
  background: var(--c-bg);
  border: 1px solid var(--c-border-soft);
  border-radius: 10px;
  padding: 12px;
  overflow: auto;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.title {
  font-weight: bold;
  font-size: 0.95rem;
}

.close {
  width: 26px;
  height: 26px;
  border: 1px solid var(--c-border-soft);
  border-radius: 50%;
  background: var(--c-panel);
  color: var(--c-text-muted);
  cursor: pointer;
}

.toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mode {
  padding: 2px 10px;
  border-radius: 10px;
  font-size: 0.75rem;
  background: var(--c-panel);
  border: 1px solid var(--c-border-soft);
  color: var(--c-text-muted);

  &.locked {
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.sep {
  width: 1px;
  height: 14px;
  background: var(--c-border-soft);
}

.tab {
  padding: 3px 12px;
  border-radius: 10px;
  border: 1px solid var(--c-border-soft);
  background: var(--c-panel);
  color: var(--c-text-muted);
  font-size: 0.78rem;
  cursor: pointer;

  &.active {
    border-color: var(--c-danger);
    color: var(--c-danger-text);
    background: var(--c-danger-bg);
  }
}

.hint {
  color: var(--c-text-faint);
  font-size: 0.72rem;
}

.empty {
  padding: 24px;
  text-align: center;
  color: var(--c-text-faint);
  border: 1.5px dashed var(--c-border-soft);
  border-radius: 8px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.thumb {
  position: relative;
  aspect-ratio: 3 / 4;
  border: 1.5px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
  padding: 0;
  background: var(--c-panel-inner);
  cursor: pointer;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
  }

  &.current {
    border-color: var(--c-danger);
  }
}

.using {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  text-align: center;
  font-size: 0.68rem;
  padding: 2px 0;
  background: rgba(20, 22, 29, 0.8);
  color: var(--c-danger-text);
}

@media (max-width: 480px) {
  .grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
