
.portrait {
  position: relative;
  width: 100%;
  overflow: hidden;
  border-radius: 8px;
  background: var(--c-panel-inner);
  border: 1px solid var(--c-border);
}

.backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(20px) brightness(0.5) saturate(0.85);
  transform: scale(1.15);
}

.main {
  position: relative;
  display: block;
  width: 100%;
  max-height: var(--portrait-cap);
  object-fit: contain;
}

.silhouette {
  width: 100%;
  aspect-ratio: 3 / 4;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1.5px dashed var(--c-border-soft);
  border-radius: 8px;
  color: var(--c-border-soft);

  svg {
    width: 64px;
    height: 86px;
  }

  span {
    font-size: 0.75rem;
  }
}

.pool-badge {
  position: absolute;
  top: 8px;
  left: 8px;
  padding: 2px 9px;
  border-radius: 9px;
  font-size: 0.7rem;
  background: var(--c-panel);
  border: 1px solid var(--c-border-soft);
  color: var(--c-text-muted);

  &.nsfw {
    background: var(--c-danger-bg);
    border-color: var(--c-danger);
    color: var(--c-danger-text);
  }
}

.actions {
  position: absolute;
  right: 8px;
  bottom: 8px;
  display: flex;
  gap: 6px;

  button {
    padding: 3px 10px;
    border: 1px solid var(--c-border-soft);
    border-radius: 6px;
    background: rgba(30, 34, 44, 0.88);
    color: var(--c-text-muted);
    font-size: 0.75rem;
    cursor: pointer;

    &:active {
      transform: translateY(1px);
    }
  }
}
