
.status-bar {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.empty-hint {
  padding: 10px;
  text-align: center;
  color: var(--c-text-faint);
  font-size: 0.85rem;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 8px;
}

.pages {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.page-row {
  display: flex;
  align-items: center;
  gap: 6px;
}

.page-viewport {
  flex: 1;
  min-width: 0;
}

.nav-btn {
  flex: none;
  width: 30px;
  height: 44px;
  border: 1px solid var(--c-border-soft);
  border-radius: 8px;
  background: var(--c-panel);
  color: var(--c-text-muted);
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  touch-action: manipulation;

  &:active {
    transform: translateY(1px);
  }
}

.dots {
  display: flex;
  justify-content: center;
  gap: 8px;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-border-soft);
  cursor: pointer;
}

.page-fade-enter-active,
.page-fade-leave-active {
  transition:
    opacity 0.18s ease,
    transform 0.18s ease;
}

.page-fade-enter-from {
  opacity: 0;
  transform: translateX(10px);
}

.page-fade-leave-to {
  opacity: 0;
  transform: translateX(-10px);
}

@media (max-width: 480px) {
  .nav-btn {
    width: 36px;
    height: 52px;
  }
}
