
.top-strip {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 12px;
  background: var(--c-panel);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  font-size: 0.85rem;
  color: var(--c-text-muted);
  overflow: hidden;
  white-space: nowrap;
}

.cell {
  overflow: hidden;
  text-overflow: ellipsis;
}

.sep {
  width: 1px;
  height: 12px;
  background: var(--c-border-soft);
  flex: none;
}

@media (max-width: 480px) {
  .top-strip {
    font-size: 0.78rem;
    gap: 6px;
  }
}
